"""px_lib: a small standard-library raster toolkit for marks that are generated by code (grids, voxels, geometry).

An RGBA buffer (`Img`), a deterministic PNG writer and reader, an ICO writer and a run-length SVG writer. Use it in a
project's own generator (tools/*.py) so a mark is rebuilt byte for byte from its source:

    import sys, os; sys.path.insert(0, os.path.join(os.environ["BRAND_CREATOR_ROOT"], "scripts", "lib"))
    from px_lib import Img, grid_image
    mark = grid_image(["..XX..", ".XXXX.", "XXAAXX"], {"X": "#101820", "A": "#00897b"})
    open("mark.svg", "w").write(mark.svg())          # one path per colour, crispEdges
    open("mark-512.png", "wb").write(mark.scaled(64).png())

Rules that keep the output reproducible: colours are written in order of first appearance, PNG chunks are fixed
(IHDR, IDAT, IEND only: no tIME, no text, no gamma), zlib runs at level 9 with default settings, and an SVG is plain
text with no timestamps. Nothing here uses the network, the clock or random numbers.
"""
from __future__ import annotations

import re
import struct
import zlib

from pxio import read_png

RGBA = tuple  # (r, g, b, a), each 0..255
_HEX = re.compile(r"^#?([0-9a-fA-F]{6}|[0-9a-fA-F]{8})$")


def rgba(c) -> RGBA:
    """'#rrggbb', '#rrggbbaa', (r, g, b) or (r, g, b, a) -> (r, g, b, a)."""
    if isinstance(c, str):
        m = _HEX.match(c.strip())
        if not m:
            raise ValueError(f"not a #rrggbb or #rrggbbaa colour: {c!r}")
        h = m.group(1)
        v = tuple(int(h[i:i + 2], 16) for i in range(0, len(h), 2))
        return v if len(v) == 4 else v + (255,)
    c = tuple(int(x) for x in c)
    if len(c) == 3:
        c += (255,)
    if len(c) != 4 or any(not 0 <= x <= 255 for x in c):
        raise ValueError(f"not an RGBA colour: {c!r}")
    return c


class Img:
    """A width x height RGBA image, row-major, 4 bytes per pixel. Transparent black unless a background is given."""

    def __init__(self, w: int, h: int, bg=None):
        if w <= 0 or h <= 0:
            raise ValueError("an image needs a positive width and height")
        self.w, self.h = w, h
        self.p = bytearray(w * h * 4)
        if bg is not None:
            self.rect(0, 0, w, h, bg)

    # -- pixels
    def set(self, x: int, y: int, c) -> None:
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 4
            self.p[i:i + 4] = bytes(rgba(c))

    def get(self, x: int, y: int) -> RGBA:
        if not (0 <= x < self.w and 0 <= y < self.h):
            raise IndexError((x, y))
        i = (y * self.w + x) * 4
        return tuple(self.p[i:i + 4])

    def rect(self, x: int, y: int, w: int, h: int, c) -> None:
        col = bytes(rgba(c))
        x0, x1 = max(0, x), min(self.w, x + w)
        if x1 <= x0:
            return
        for yy in range(max(0, y), min(self.h, y + h)):
            a = (yy * self.w + x0) * 4
            self.p[a:a + 4 * (x1 - x0)] = col * (x1 - x0)

    def blit(self, other: "Img", x: int, y: int, k: int = 1) -> None:
        """Copy the non-transparent pixels of other, each enlarged k times, with its top-left at (x, y)."""
        for yy in range(other.h):
            for xx in range(other.w):
                c = other.get(xx, yy)
                if c[3]:
                    self.rect(x + xx * k, y + yy * k, k, k, c)

    def scaled(self, k: int) -> "Img":
        """Nearest-neighbour enlargement by a whole factor k (the only scaling that keeps a pixel mark exact)."""
        if k < 1:
            raise ValueError("scale factor must be a whole number of 1 or more")
        out = Img(self.w * k, self.h * k)
        for y in range(self.h):
            row = bytearray()
            for x in range(self.w):
                i = (y * self.w + x) * 4
                row += bytes(self.p[i:i + 4]) * k
            for dy in range(k):
                a = ((y * k + dy) * out.w) * 4
                out.p[a:a + len(row)] = row
        return out

    def crop(self, x: int, y: int, w: int, h: int) -> "Img":
        out = Img(w, h)
        for yy in range(h):
            for xx in range(w):
                if 0 <= x + xx < self.w and 0 <= y + yy < self.h:
                    i = ((y + yy) * self.w + x + xx) * 4
                    j = (yy * w + xx) * 4
                    out.p[j:j + 4] = self.p[i:i + 4]
        return out

    def bbox(self):
        """(x0, y0, x1, y1) inclusive bounds of the pixels with alpha > 0, or None for an empty image."""
        xs, ys = [], []
        for y in range(self.h):
            for x in range(self.w):
                if self.p[(y * self.w + x) * 4 + 3]:
                    xs.append(x)
                    ys.append(y)
        return (min(xs), min(ys), max(xs), max(ys)) if xs else None

    def colours(self) -> list[RGBA]:
        """Distinct opaque-or-partial colours in order of first appearance (transparent pixels skipped)."""
        seen: dict[RGBA, None] = {}
        for i in range(0, len(self.p), 4):
            c = tuple(self.p[i:i + 4])
            if c[3]:
                seen.setdefault(c)
        return list(seen)

    def __eq__(self, other) -> bool:
        return isinstance(other, Img) and (self.w, self.h, bytes(self.p)) == (other.w, other.h, bytes(other.p))

    # -- writers
    def png(self) -> bytes:
        """A PNG with only IHDR, IDAT and IEND: the same pixels always give the same bytes."""
        raw = b"".join(b"\0" + bytes(self.p[y * self.w * 4:(y + 1) * self.w * 4]) for y in range(self.h))

        def chunk(t: bytes, d: bytes) -> bytes:
            return struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d) & 0xFFFFFFFF)

        return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", self.w, self.h, 8, 6, 0, 0, 0))
                + chunk(b"IDAT", zlib.compress(raw, 9)) + chunk(b"IEND", b""))

    def png_rgb(self) -> bytes:
        """The same deterministic PNG with NO alpha channel (colour type 2). Raises when a pixel is not fully opaque:
        flatten onto a ground first (an App Store icon, a BMP source)."""
        if any(self.p[i] != 255 for i in range(3, len(self.p), 4)):
            raise ValueError("png_rgb() needs a fully opaque image; flatten it onto a ground first")
        rows = []
        for y in range(self.h):
            src = self.p[y * self.w * 4:(y + 1) * self.w * 4]
            row = bytearray(3 * self.w)
            row[0::3], row[1::3], row[2::3] = src[0::4], src[1::4], src[2::4]
            rows.append(b"\0" + bytes(row))
        raw = b"".join(rows)

        def chunk(t: bytes, d: bytes) -> bytes:
            return struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d) & 0xFFFFFFFF)

        return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", self.w, self.h, 8, 2, 0, 0, 0))
                + chunk(b"IDAT", zlib.compress(raw, 9)) + chunk(b"IEND", b""))

    def svg(self, scale: int = 1, cls: str = "", title: str | None = None) -> str:
        """Run-length SVG: one <path> per colour, runs of equal pixels in a row merged, shape-rendering crispEdges.

        Pixels with partial alpha get fill-opacity. The viewBox is the pixel grid; width and height are the grid times scale."""
        runs: dict[RGBA, list[str]] = {}
        for y in range(self.h):
            x = 0
            while x < self.w:
                c = self.get(x, y)
                if not c[3]:
                    x += 1
                    continue
                x2 = x
                while x2 < self.w and self.get(x2, y) == c:
                    x2 += 1
                runs.setdefault(c, []).append(f"M{x} {y}h{x2 - x}v1h-{x2 - x}z")
                x = x2
        paths = ""
        for c, d in runs.items():
            op = "" if c[3] == 255 else f' fill-opacity="{c[3] / 255:.3f}"'
            paths += f'<path fill="#{c[0]:02x}{c[1]:02x}{c[2]:02x}"{op} d="{"".join(d)}"/>'
        klass = f' class="{cls}"' if cls else ""
        t = f"<title>{title}</title>" if title else ""
        return (f'<svg xmlns="http://www.w3.org/2000/svg"{klass} viewBox="0 0 {self.w} {self.h}" width="{self.w * scale}" '
                f'height="{self.h * scale}" shape-rendering="crispEdges">{t}{paths}</svg>')


def grid_image(rows: list[str], palette: dict[str, str], *, empty: str = ".") -> Img:
    """A mark drawn as text: each character of a row is a cell, `empty` is transparent, others look up `palette`."""
    if not rows or len({len(r) for r in rows}) != 1:
        raise ValueError("grid rows must be non-empty and all the same length")
    img = Img(len(rows[0]), len(rows))
    for y, row in enumerate(rows):
        for x, ch in enumerate(row):
            if ch == empty:
                continue
            if ch not in palette:
                raise ValueError(f"grid cell {ch!r} at row {y} column {x} has no colour in the palette")
            img.set(x, y, palette[ch])
    return img


def from_png(data: bytes) -> Img:
    """Read an 8-bit PNG (colour types 0, 2, 3, 4, 6, no interlace) into an Img."""
    w, h, px = read_png(data)
    img = Img(w, h)
    img.p[:] = px
    return img


def ico(imgs: list[Img]) -> bytes:
    """ICO with PNG-compressed entries in the order given (256 is stored as 0, as the format requires)."""
    data = [i.png() for i in imgs]
    off = 6 + 16 * len(imgs)
    out = struct.pack("<HHH", 0, 1, len(imgs))
    ents = b""
    for im, d in zip(imgs, data):
        if im.w > 256 or im.h > 256:
            raise ValueError("an ICO entry is at most 256 x 256")
        ents += struct.pack("<BBBBHHII", im.w % 256, im.h % 256, 0, 0, 1, 32, len(d), off)
        off += len(d)
    return out + ents + b"".join(data)
